function dfs(graph, node, visited, path, result) {
    visited.set(node, true);
    path.push(node);

    // If reached destination, save path
    if (node === destination) {
        result.push([...path]);
    } else {
        for (const neighbor of graph.get(node)) {
            if (!visited.has(neighbor)) {
                dfs(graph, neighbor, visited, path, result);
            }
        }
    }
    path.pop();
}
